    comp = [(r,c)]
    q = deque([(r,c)])
    visited.add((r,c))
    while q:
        rr, cc = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = rr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr,nc) not in visited and grid[nr][nc] == 0:
                visited.add((nr,nc))
                comp.append((nr,nc))
                q.append((nr,nc))
    return comp

