# Maybe it's: fill 0s where BOTH |r - marker_row| <= K AND |c - marker_col| <= K for some K

def compute_bounding_box_around_markers(grid, rows, cols, markers, max_dist):
    result = set()
    for mr, mc in markers:
        for r in range(max(0, mr-max_dist), min(rows, mr+max_dist+1)):
            for c in range(max(0, mc-max_dist), min(cols, mc+max_dist+1)):
                if grid[r][c] == 0:
                    result.add((r,c))
    return result

