from collections import deque

def bfs_8way(source_cells, grid, rows, cols):
    """Get all reachable cells via 8-way paths through any starting cells"""
    visited = set()
    q = deque(list(source_cells))
    result = set()

    while q:
        r,c = q.popleft()
        if (r,c) in visited:
            continue
        visited.add((r,c))

        for dr in [-1,0,1]:
            for dc in [-1,0,1]:
                if dr==0 and dc==0:
                    continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 0 and (nr,nc) not in visited:
                        q.append((nr,nc))
                        result.add((nr,nc))
    return result

