    diag_sum = r0 + c0
    for r in range(min(rows, rows-diag_sum)):
        c = diag_sum - r
        if 0 <= c < cols:
            result.add((r,c))
    for r in range(max(0, diag_sum-cols+1), rows):
        c = diag_sum - r
        if 0 <= c < cols:
            result.add((r,c))

    return result

