from collections import deque, defaultdict

def find_connected_components(markers, rows, cols):
    """Find which markers are connected via adjacency"""
    visited = set()
    components = []

    def dfs(pos):
        stack = [pos]
        comp = {pos}
        while stack:
            r,c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))

            # Check 8-way neighbors
            for dr in [-1,0,1]:
                for dc in [-1,0,1]:
                    if dr==0 and dc==0:
                        continue
                    nr, nc = r+dr, c+dc
                    if (nr,nc) in markers and (nr,nc) not in visited:
                        stack.append((nr,nc))
                        comp.add((nr,nc))
        return comp

    for m in markers:
        if m not in visited:
            comp = dfs(m)
            if comp:
                components.append(comp)

    return components

