from collections import deque

def has_clear_diagonal_to_marker(pos, grid, rows, cols, targets):
    """Check if pos has clear diagonal (main or anti) to any target through only zeros"""
    r,c = pos

    for tr,tc in targets:
        # Anti-diagonal
        if r - c == tr - tc:
            # Check if path is clear
            dr = 1 if r > tr else -1
            dc = 1 if c > tc else -1

            curr_r, curr_c = r, c
            while abs(curr_r - tr) < abs(r - tr):
                curr_r += dr
                curr_c += dc
                if curr_r >= rows or curr_c >= cols:
                    return False
                if grid[curr_r][curr_c] != 0:
                    return False

            if curr_r >= 0 and curr_c >= 0 and grid[curr_r][curr_c] != 0:
                return True

        # Main diagonal
        if r + c == tr + tc:
            dr = 1 if r > tr else -1
            dc = -dr  # Opposite direction for main diag

            curr_r, curr_c = r, c
            while abs(curr_r - tr) < abs(r - tr):
                curr_r += dr
                curr_c += dc
                if curr_r >= rows or curr_c >= cols:
                    return False
                if grid[curr_r][curr_c] != 0:
                    return False

            if curr_r >= 0 and curr_c >= 0:
                return True

    return False

